  '["Recherche et rédaction journalistique.","Présentation et animation radiophonique et télévisuelle.","Stratégies de communication et publicité.","Photographie et vidéographie.","Gestion et analyse de l''information."]'::jsonb, '["Microsoft Word","Microsoft Excel","Microsoft PowerPoint","Adobe Premiere Pro","Final Cut Pro","Cubase","Audacity"]'::jsonb, '[{"id":"lang-ht","name":"Créole haïtien","level":"Langue maternelle"},{"id":"lang-fr","name":"Français","level":"Niveau avancé"},{"id":"lang-en","name":"Anglais","level":"Niveau débutant"}]'::jsonb
